module IconsHelper
  # Renders a Heroicon (outline, 24x24, stroke 1.5) by name.
  # Usage: <%= icon(:plus, class: "h-5 w-5") %>
  def icon(name, class: "h-5 w-5", **options)
    paths = HEROICONS.fetch(name) { raise ArgumentError, "Unknown icon: #{name}" }
    css = binding.local_variable_get(:class)

    content_tag(:svg,
      paths.html_safe,
      class: css,
      fill: "none",
      viewBox: "0 0 24 24",
      "stroke-width": "1.5",
      stroke: "currentColor",
      "aria-hidden": "true",
      **options)
  end

